import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Thermometer, Droplets, Radar as RadarIcon, Wifi } from 'lucide-react';

// ---------------------------------------------------------------------------
// Sensor Station — live dashboard for a DHT-style temp/humidity sensor and a
// PIR motion detector.
//
// This component SIMULATES sensor data locally so it works standalone. To
// wire it to a real device, replace the `pollSensors()` function below with
// a fetch() call to your device's API / MQTT bridge, e.g.:
//
//   async function pollSensors() {
//     const res = await fetch('/api/sensors/latest');
//     return await res.json(); // { temperature, humidity, motion }
//   }
//
// and call `applyReading(data)` with the result on an interval.
// ---------------------------------------------------------------------------

const HISTORY_LEN = 40;
const MOTION_WINDOW_MS = 10 * 60 * 1000; // 10 minute rolling timeline

function useSparklinePath(values, min, max, width, height) {
  if (values.length < 2) return '';
  const range = Math.max(max - min, 0.001);
  const step = width / (HISTORY_LEN - 1);
  const offset = HISTORY_LEN - values.length;
  return values
    .map((v, i) => {
      const x = (offset + i) * step;
      const y = height - ((v - min) / range) * height;
      return `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(' ');
}

function formatClock(d) {
  return d.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
}

function timeAgo(ts) {
  if (!ts) return '—';
  const s = Math.floor((Date.now() - ts) / 1000);
  if (s < 5) return 'gerade eben';
  if (s < 60) return `vor ${s}s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `vor ${m} Min`;
  const h = Math.floor(m / 60);
  return `vor ${h} Std`;
}

export default function SensorDashboard() {
  const [now, setNow] = useState(new Date());
  const [temp, setTemp] = useState(22.4);
  const [hum, setHum] = useState(47.5);
  const [tempHistory, setTempHistory] = useState([22.4]);
  const [humHistory, setHumHistory] = useState([47.5]);
  const [tempMinMax, setTempMinMax] = useState([22.4, 22.4]);
  const [humMinMax, setHumMinMax] = useState([47.5, 47.5]);
  const [motionActive, setMotionActive] = useState(false);
  const [lastMotion, setLastMotion] = useState(null);
  const [motionLog, setMotionLog] = useState([]);
  const [connected, setConnected] = useState(true);
  const motionTimeout = useRef(null);

  const applyReading = useCallback((data) => {
    if (typeof data.temperature === 'number') {
      setTemp(data.temperature);
      setTempHistory((h) => [...h.slice(-(HISTORY_LEN - 1)), data.temperature]);
      setTempMinMax(([mn, mx]) => [Math.min(mn, data.temperature), Math.max(mx, data.temperature)]);
    }
    if (typeof data.humidity === 'number') {
      setHum(data.humidity);
      setHumHistory((h) => [...h.slice(-(HISTORY_LEN - 1)), data.humidity]);
      setHumMinMax(([mn, mx]) => [Math.min(mn, data.humidity), Math.max(mx, data.humidity)]);
    }
    if (data.motion) {
      const t = Date.now();
      setMotionActive(true);
      setLastMotion(t);
      setMotionLog((log) => [...log, t].filter((ts) => t - ts < MOTION_WINDOW_MS));
      clearTimeout(motionTimeout.current);
      motionTimeout.current = setTimeout(() => setMotionActive(false), 4000);
    }
  }, []);

  // --- Simulated sensor feed. Swap this block for a real API poll. ---
  useEffect(() => {
    const tick = setInterval(() => {
      setNow(new Date());
      const nextTemp = Math.min(27, Math.max(18, temp + (Math.random() - 0.5) * 0.3));
      const nextHum = Math.min(65, Math.max(30, hum + (Math.random() - 0.5) * 1.2));
      const motionEvent = Math.random() < 0.06;
      applyReading({ temperature: nextTemp, humidity: nextHum, motion: motionEvent });
    }, 1800);
    return () => clearInterval(tick);
  }, [temp, hum, applyReading]);

  useEffect(() => {
    const flicker = setInterval(() => {
      setConnected(Math.random() > 0.03);
    }, 6000);
    return () => clearInterval(flicker);
  }, []);

  const tempPath = useSparklinePath(tempHistory, tempMinMax[0] - 0.5, tempMinMax[1] + 0.5, 220, 56);
  const humPath = useSparklinePath(humHistory, humMinMax[0] - 2, humMinMax[1] + 2, 220, 56);

  const prefersReducedMotion =
    typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

  return (
    <div className="ss-root">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap');

        .ss-root {
          --bg: #15181b;
          --panel: #1c2024;
          --panel-raised: #21262b;
          --line: #2a3136;
          --text: #edeff1;
          --text-dim: #838d94;
          --text-faint: #4d565c;
          --warm: #ff8f5e;
          --warm-dim: #ff8f5e33;
          --cool: #52c7e0;
          --cool-dim: #52c7e033;
          --alert: #f2c744;
          --alert-dim: #f2c74433;
          --ok: #5fd08a;
          --radius: 10px;
          font-family: 'Space Grotesk', -apple-system, sans-serif;
          background: var(--bg);
          color: var(--text);
          padding: 28px;
          min-height: 100%;
          box-sizing: border-box;
        }
        .ss-root * { box-sizing: border-box; }
        .ss-mono { font-family: 'JetBrains Mono', ui-monospace, monospace; }

        .ss-header {
          display: flex;
          align-items: baseline;
          justify-content: space-between;
          margin-bottom: 22px;
          padding-bottom: 16px;
          border-bottom: 1px solid var(--line);
          flex-wrap: wrap;
          gap: 10px;
        }
        .ss-title-block { display: flex; align-items: baseline; gap: 12px; }
        .ss-eyebrow {
          font-size: 11px;
          letter-spacing: 0.16em;
          color: var(--text-faint);
          text-transform: uppercase;
        }
        .ss-title {
          font-size: 20px;
          font-weight: 700;
          letter-spacing: 0.02em;
        }
        .ss-status {
          display: flex;
          align-items: center;
          gap: 8px;
          font-size: 12px;
          color: var(--text-dim);
        }
        .ss-dot {
          width: 7px;
          height: 7px;
          border-radius: 50%;
          background: var(--ok);
          box-shadow: 0 0 0 3px color-mix(in srgb, var(--ok) 20%, transparent);
        }
        .ss-dot.down { background: var(--alert); box-shadow: 0 0 0 3px color-mix(in srgb, var(--alert) 20%, transparent); }
        .ss-clock { color: var(--text-dim); }

        .ss-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 14px;
          margin-bottom: 14px;
        }
        @media (max-width: 640px) {
          .ss-grid { grid-template-columns: 1fr; }
        }

        .ss-card {
          background: var(--panel);
          border: 1px solid var(--line);
          border-radius: var(--radius);
          padding: 18px 20px;
        }
        .ss-card-head {
          display: flex;
          align-items: center;
          justify-content: space-between;
          margin-bottom: 14px;
        }
        .ss-label {
          font-size: 11px;
          letter-spacing: 0.14em;
          text-transform: uppercase;
          color: var(--text-dim);
          display: flex;
          align-items: center;
          gap: 7px;
        }
        .ss-reading {
          display: flex;
          align-items: flex-end;
          gap: 4px;
          margin-bottom: 12px;
        }
        .ss-value {
          font-size: 40px;
          font-weight: 500;
          line-height: 1;
          letter-spacing: -0.01em;
        }
        .ss-unit {
          font-size: 16px;
          color: var(--text-dim);
          padding-bottom: 4px;
        }
        .ss-minmax {
          font-size: 11px;
          color: var(--text-faint);
          display: flex;
          gap: 14px;
          margin-top: 10px;
        }
        .ss-spark { display: block; overflow: visible; }

        .ss-motion {
          background: var(--panel);
          border: 1px solid var(--line);
          border-radius: var(--radius);
          padding: 20px 22px;
          display: grid;
          grid-template-columns: auto 1fr;
          gap: 22px;
          align-items: center;
        }
        @media (max-width: 640px) {
          .ss-motion { grid-template-columns: 1fr; justify-items: center; text-align: center; }
        }

        .ss-radar-wrap { position: relative; width: 86px; height: 86px; flex-shrink: 0; }
        .ss-radar-ring {
          position: absolute; inset: 0;
          border-radius: 50%;
          border: 1px solid var(--line);
        }
        .ss-radar-ring.mid { inset: 14px; }
        .ss-radar-ring.core { inset: 30px; display: flex; align-items: center; justify-content: center; }
        .ss-radar-sweep {
          position: absolute; inset: 0;
          border-radius: 50%;
          background: conic-gradient(from 0deg, transparent 0deg, color-mix(in srgb, var(--cool) 55%, transparent) 28deg, transparent 56deg);
          animation: ss-spin 3.2s linear infinite;
        }
        .ss-motion.triggered .ss-radar-sweep {
          background: conic-gradient(from 0deg, transparent 0deg, color-mix(in srgb, var(--alert) 70%, transparent) 30deg, transparent 60deg);
          animation-duration: 1.1s;
        }
        @keyframes ss-spin { to { transform: rotate(360deg); } }
        .ss-radar-dot {
          width: 10px; height: 10px; border-radius: 50%;
          background: var(--cool);
          box-shadow: 0 0 10px 2px var(--cool-dim);
          transition: background 0.2s, box-shadow 0.2s;
        }
        .ss-motion.triggered .ss-radar-dot {
          background: var(--alert);
          box-shadow: 0 0 14px 4px var(--alert-dim);
        }

        .ss-motion-info { min-width: 0; }
        .ss-motion-status {
          font-size: 19px;
          font-weight: 600;
          margin-bottom: 3px;
          transition: color 0.2s;
        }
        .ss-motion.triggered .ss-motion-status { color: var(--alert); }
        .ss-motion-sub { font-size: 12px; color: var(--text-dim); margin-bottom: 14px; }

        .ss-timeline {
          position: relative;
          height: 26px;
          border-top: 1px solid var(--line);
          padding-top: 8px;
        }
        .ss-timeline-label {
          font-size: 10px;
          color: var(--text-faint);
          letter-spacing: 0.1em;
          text-transform: uppercase;
          margin-bottom: 4px;
        }
        .ss-tick {
          position: absolute;
          bottom: 8px;
          width: 2px;
          height: 14px;
          background: var(--alert);
          border-radius: 1px;
          opacity: 0.85;
        }
      `}</style>

      <header className="ss-header">
        <div className="ss-title-block">
          <div>
            <div className="ss-eyebrow">Sensor Station</div>
            <div className="ss-title">Klima &amp; Bewegung — Wohnraum</div>
          </div>
        </div>
        <div className="ss-status">
          <span className={`ss-dot ${connected ? '' : 'down'}`} />
          <Wifi size={13} strokeWidth={2} />
          <span>{connected ? 'Verbunden' : 'Verbindung instabil'}</span>
          <span className="ss-mono ss-clock">{formatClock(now)}</span>
        </div>
      </header>

      <div className="ss-grid">
        <div className="ss-card">
          <div className="ss-card-head">
            <span className="ss-label">
              <Thermometer size={13} color="var(--warm)" strokeWidth={2} />
              Temperatur
            </span>
          </div>
          <div className="ss-reading">
            <span className="ss-value ss-mono" style={{ color: 'var(--warm)' }}>
              {temp.toFixed(1)}
            </span>
            <span className="ss-unit ss-mono">°C</span>
          </div>
          <svg className="ss-spark" viewBox="0 0 220 56" width="100%" height="56" preserveAspectRatio="none">
            <path d={tempPath} fill="none" stroke="var(--warm)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          <div className="ss-minmax ss-mono">
            <span>MIN {tempMinMax[0].toFixed(1)}°</span>
            <span>MAX {tempMinMax[1].toFixed(1)}°</span>
          </div>
        </div>

        <div className="ss-card">
          <div className="ss-card-head">
            <span className="ss-label">
              <Droplets size={13} color="var(--cool)" strokeWidth={2} />
              Luftfeuchtigkeit
            </span>
          </div>
          <div className="ss-reading">
            <span className="ss-value ss-mono" style={{ color: 'var(--cool)' }}>
              {hum.toFixed(0)}
            </span>
            <span className="ss-unit ss-mono">%</span>
          </div>
          <svg className="ss-spark" viewBox="0 0 220 56" width="100%" height="56" preserveAspectRatio="none">
            <path d={humPath} fill="none" stroke="var(--cool)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          <div className="ss-minmax ss-mono">
            <span>MIN {humMinMax[0].toFixed(0)}%</span>
            <span>MAX {humMinMax[1].toFixed(0)}%</span>
          </div>
        </div>
      </div>

      <div className={`ss-motion ${motionActive ? 'triggered' : ''}`}>
        <div className="ss-radar-wrap">
          <div className="ss-radar-ring" />
          <div className="ss-radar-ring mid" />
          {!prefersReducedMotion && <div className="ss-radar-sweep" />}
          <div className="ss-radar-ring core">
            <div className="ss-radar-dot" />
          </div>
        </div>

        <div className="ss-motion-info">
          <div className="ss-card-head" style={{ marginBottom: 2 }}>
            <span className="ss-label">
              <RadarIcon size={13} color={motionActive ? 'var(--alert)' : 'var(--text-dim)'} strokeWidth={2} />
              Bewegungsmelder
            </span>
          </div>
          <div className="ss-motion-status">
            {motionActive ? 'Bewegung erkannt' : 'Ruhig — keine Bewegung'}
          </div>
          <div className="ss-motion-sub">
            Letztes Ereignis: {timeAgo(lastMotion)} · {motionLog.length} Ereignis{motionLog.length === 1 ? '' : 'se'} in den letzten 10 Min
          </div>

          <div className="ss-timeline-label">Verlauf · 10 Min</div>
          <div className="ss-timeline">
            {motionLog.map((ts, i) => {
              const pct = Math.max(0, Math.min(100, (1 - (Date.now() - ts) / MOTION_WINDOW_MS) * 100));
              return <div key={i} className="ss-tick" style={{ left: `${pct}%` }} />;
            })}
          </div>
        </div>
      </div>
    </div>
  );
}
